ON CONFLICT (edge_id) DO UPDATE SET
    edge_code = EXCLUDED.edge_code,
    from_node_id = EXCLUDED.from_node_id,
    to_node_id = EXCLUDED.to_node_id,
    distance = EXCLUDED.distance,
    direction_type = EXCLUDED.direction_type,
    edge_type = EXCLUDED.edge_type,
    speed_limit_mps = EXCLUDED.speed_limit_mps,
    nominal_travel_time_ms = EXCLUDED.nominal_travel_time_ms,
    cost = EXCLUDED.cost,
    physical_resource_code = EXCLUDED.physical_resource_code,
    service_only = EXCLUDED.service_only,
    mobile_robot_traversable = EXCLUDED.mobile_robot_traversable,
    route_attributes = EXCLUDED.route_attributes;

SELECT setval(pg_get_serial_sequence('warehouse_node', 'node_id'),
    GREATEST((SELECT COALESCE(MAX(node_id), 1) FROM public.warehouse_node), 1), TRUE);
SELECT setval(pg_get_serial_sequence('warehouse_edge', 'edge_id'),
    GREATEST((SELECT COALESCE(MAX(edge_id), 1) FROM public.warehouse_edge), 1), TRUE);

DO $$
DECLARE
    total_nodes integer;
    actual_nodes integer;
    actual_edges integer;
BEGIN
    SELECT count(*) INTO total_nodes
    FROM public.warehouse_node
    WHERE warehouse_id = 1;

    SELECT count(*) INTO actual_nodes
    FROM public.warehouse_node
    WHERE warehouse_id = 1 AND is_active = TRUE;

    SELECT count(*) INTO actual_edges
    FROM public.warehouse_edge
    WHERE from_node_id IN (
        SELECT node_id FROM public.warehouse_node
        WHERE warehouse_id = 1 AND is_active = TRUE
    );

    IF total_nodes <> 290 OR actual_nodes <> 171 OR actual_edges <> 392 THEN
        RAISE EXCEPTION 'V09 warehouse map verification failed: total_nodes=%, active_nodes=%, edges=%',
            total_nodes, actual_nodes, actual_edges;
    END IF;
END
$$;

COMMIT;

